import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import { OBJLoader } from 'three/examples/jsm/loaders/OBJLoader';
import * as THREE from 'three';
import './App.css';

// Device Capability Detection Utility
const DeviceCapabilities = {
  // Determine device performance tier
  getPerformanceTier() {
    // Check WebGL support and version
    const canvas = document.createElement('canvas');
    const gl = canvas.getContext('webgl2') || canvas.getContext('webgl');

    // Check device GPU capabilities
    const maxTextureSize = gl ? gl.getParameter(gl.MAX_TEXTURE_SIZE) : 0;
    const maxVertexTextures = gl ? gl.getParameter(gl.MAX_VERTEX_TEXTURE_IMAGE_UNITS) : 0;

    // Check memory and processing capabilities
    const deviceMemory = navigator.deviceMemory || 4; // Default to 4GB if not available
    const hardwareConcurrency = navigator.hardwareConcurrency || 4; // Default to 4 cores

    // Performance scoring algorithm
    let score = 0;

    // WebGL capabilities
    if (maxTextureSize >= 8192) score += 3;
    else if (maxTextureSize >= 4096) score += 2;
    else if (maxTextureSize >= 2048) score += 1;

    // Memory check
    if (deviceMemory >= 8) score += 3;
    else if (deviceMemory >= 4) score += 2;
    else if (deviceMemory >= 2) score += 1;

    // CPU cores
    if (hardwareConcurrency >= 8) score += 3;
    else if (hardwareConcurrency >= 4) score += 2;
    else if (hardwareConcurrency >= 2) score += 1;

    // Categorize performance tier
    if (score >= 7) return 'high';
    if (score >= 4) return 'medium';
    return 'low';
  }
};

// Updated Model Caching Hook
const useModelCache = () => {
  const [modelCache, setModelCache] = useState({});
  const [loadingModels, setLoadingModels] = useState({});
  const performanceTier = useMemo(() => DeviceCapabilities.getPerformanceTier(), []);

  const loadModel = useCallback((modelData) => {
    // Determine which model to load based on device performance
    const modelPath = performanceTier === 'low' && modelData.alt 
      ? `./stls/${modelData.alt}` 
      : `./stls/${modelData.file}`;

    return new Promise((resolve, reject) => {
      // Check if model is already cached
      if (modelCache[modelPath]) {
        resolve(modelCache[modelPath]);
        return;
      }

      // Check if model is currently loading
      if (loadingModels[modelPath]) {
        loadingModels[modelPath].then(resolve);
        return;
      }

      const loader = new OBJLoader();
      const modelLoading = new Promise((innerResolve, innerReject) => {
        loader.load(
          modelPath,
          (obj) => {
            const newModelRef = new THREE.Group();

            const box = new THREE.Box3().setFromObject(obj);
            const size = box.getSize(new THREE.Vector3());
            const maxDimension = Math.max(size.x, size.y, size.z);
            obj.rotation.x = -Math.PI / 2;
            const scaleFactor = 2.5 / maxDimension;
            obj.scale.set(scaleFactor, scaleFactor, scaleFactor);

            box.setFromObject(obj);
            const center = box.getCenter(new THREE.Vector3());
            obj.position.sub(center);

            obj.traverse((child) => {
              if (child.isMesh) {
                const edges = new THREE.EdgesGeometry(child.geometry, 45);
                const lineMaterial = new THREE.LineBasicMaterial({
                  color: 0xffffff,
                  opacity: performanceTier === 'low' ? 0.2 : 0.5,
                  transparent: true,
                });
                const edgeLines = new THREE.LineSegments(edges, lineMaterial);
                edgeLines.position.copy(child.position);
                edgeLines.rotation.copy(child.rotation);
                edgeLines.scale.copy(child.scale);
                child.parent.add(edgeLines);
                child.parent.remove(child);
              }
            });

            newModelRef.add(obj);

            // Update cache
            setModelCache(prev => ({
              ...prev,
              [modelPath]: newModelRef
            }));

            // Remove from loading models
            setLoadingModels(prev => {
              const updated = {...prev};
              delete updated[modelPath];
              return updated;
            });

            innerResolve(newModelRef);
            resolve(newModelRef);
          },
          undefined,
          (error) => {
            innerReject(error);
            reject(error);
          }
        );
      });

      // Track loading models
      setLoadingModels(prev => ({
        ...prev,
        [modelPath]: modelLoading
      }));

      return modelLoading;
    });
  }, [modelCache, performanceTier]);

  return { modelCache, loadModel, performanceTier };
};

const ModelLoader = ({ modelData }) => {
  const [model, setModel] = useState(null);
  const { loadModel } = useModelCache();
  const groupRef = useRef(null);

  useEffect(() => {
    loadModel(modelData)
      .then(setModel)
      .catch(error => console.error('Error loading OBJ:', error));
  }, [modelData, loadModel]);

  // Apply rotations to the model group
  useFrame(() => {
    if (groupRef.current) {
      groupRef.current.rotation.y += 0.003;
    }
  });

  return (
    <group ref={groupRef}>
      {!model && (
        <mesh>
          <boxGeometry args={[1, 1, 1]} />
          <meshBasicMaterial color="white" wireframe={true} />
        </mesh>
      )}
      {model && <primitive object={model} />}
    </group>
  );
};

const App = () => {
  const [models, setModels] = useState([]);
  const [selectedModel, setSelectedModel] = useState(null);
  const [highlightedModel, setHighlightedModel] = useState(null);
  const [asciiArt, setAsciiArt] = useState('');
  const [asciiIndex, setAsciiIndex] = useState(0);
  const [asciiComplete, setAsciiComplete] = useState(false);
  const { modelCache, loadModel, performanceTier } = useModelCache();

  // Add performance tier logging
  useEffect(() => {
    console.log('Device Performance Tier:', performanceTier);
  }, [performanceTier]);

  useEffect(() => {
    fetch('./models.json')
      .then((response) => response.json())
      .then((data) => {
        setModels(data);
        setSelectedModel(data[0]?.file);

        // Preload all models in the background
        data.forEach(model => {
          loadModel(model);
        });
      })
      .catch((error) => console.error('Error loading models:', error));
  }, []);

  // ... rest of the existing App component code remains the same ...

  return (
    <div className="container">
      {/* Existing sidebar code */}
      <div className="right-container">
        {!asciiComplete && (
          <div className="ascii-art">
            {asciiArt}
          </div>
        )}

        {asciiComplete && (
          <Canvas
            style={{ backgroundColor: 'black' }}
            camera={{
              position: [2.5, 2.5, 2.5],
              fov: 45,
            }}
          >
            <ambientLight intensity={0.5} />
            <spotLight position={[10, 10, 10]} intensity={1} />
            <directionalLight position={[5, 5, 5]} intensity={1} />
            {selectedModel && (
              <ModelLoader 
                modelData={
                  models.find(model => model.file === selectedModel) || {}
                } 
              />
            )}
            <OrbitControls
              enableZoom={false}
              minPolarAngle={Math.PI / 4}
              maxPolarAngle={Math.PI / 4}
              minAzimuthAngle={-Math.PI / 4}
              maxAzimuthAngle={Math.PI / 4}
            />
          </Canvas>
        )}
      </div>
    </div>
  );
};

export default App;
